fn parse_backslash(&mut self) -> Result<(), Error> {
    if self.opts.backslash_escape {
        match self.bump() {
            None => Err(self.error(ErrorKind::DanglingEscape)),
            Some(c) => self.push_token(Token::Literal(c)),
        }
